package com.retailflow.pos.sales;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.retailflow.pos.ledger.LedgerService;import com.retailflow.pos.product.*;import com.retailflow.pos.stock.StockMovementService;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.Test;
class SalesServiceTest{@Test void calculatesGstInclusiveInvoiceTotal(){var invoices=mock(InvoiceRepository.class);var products=mock(ProductRepository.class);var stock=mock(StockMovementService.class);var ledger=mock(LedgerService.class);when(products.findById("p1")).thenReturn(Optional.of(Product.builder().id("p1").name("Shirt").stock(BigDecimal.TEN).build()));when(invoices.save(any())).thenAnswer(i->i.getArgument(0));var service=new SalesService(invoices,products,stock,ledger);var invoice=Invoice.builder().invoiceNo("INV-1").discount(BigDecimal.ZERO).items(List.of(InvoiceItem.builder().productId("p1").quantity(new BigDecimal("2")).unitPrice(new BigDecimal("100")).gstRate(new BigDecimal("5")).build())).build();var saved=service.create(invoice,"owner");assertEquals(new BigDecimal("210.00"),saved.getTotal());}}
